  let cancelled = false
  const native: PaintMark[] = []
  void (async () => {
    for (let start = 0; start < document.pages.length && !cancelled; start += 2) {
      const batch = await Promise.all(document.pages.slice(start, start + 2).map(async page => {
        try {
          const annotations = await engine.getPageAnnotations(document, page).toPromise()
          return annotations.flatMap(annotation => {
            const note = annotation.contents?.trim() ?? ''
            if (note === '') return []
